int n, s, count;
int used[10];

void dfs(int pos, int sum) {
    if (pos == n) {
        if (sum == s) count++;
        return;
    }
    // Prune: even if we add max possible weights for remaining positions, can't reach s
    int remaining = n - pos;
    int max_possible = sum + (9 * (pos + 1)) + (9 * (pos + 2)) / 2 * remaining;
    if (max_possible < s) return;

    for (int d = 0; d <= 9; d++) {
        if (!used[d]) {
            used[d] = 1;
            dfs(pos + 1, sum + (pos + 1) * d);
            used[d] = 0;
        }
    }
}

