    for (int pos = 0; pos < n; pos++) {
        int weight = pos + 1;
        for (int mask = 0; mask < (1 << 10); mask++) {
            for (int sum = 0; sum <= s; sum++) {
                long long cur = dp[pos][mask][sum];
                if (!cur) continue;

                for (int digit = 0; digit <= 9; digit++) {
                    if (mask & (1 << digit)) continue; // no repeated digits
                    int nsum = sum + weight * digit;
                    if (nsum <= s) {
                        dp[pos + 1][mask | (1 << digit)][nsum] += cur;
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int mask = 0; mask < (1 << 10); mask++) {
        ans += dp[n][mask][s];
    }

    printf("%lld\n", ans);
    return 0;
}

