        if (idx == n) {
            if (currentSum == s) {
                count++;
            }
            return;
        }

        for (int digit = 0; digit <= 9; digit++) {
            if (!used[digit]) {
                used[digit] = true;
                backtrack(idx + 1, currentSum + (idx + 1) * digit);
                used[digit] = false;
            }
        }
    }
