public class Main {
    static int n, s;
    static long[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            n = sc.nextInt();
            s = sc.nextInt();
            // memo[mask][sum]: number of ways from current state
            // max sum = 9*(1+2+...+n) = 9*n*(n+1)/2
            int maxSum = 9 * n * (n + 1) / 2;
            memo = new long[1 << 10][maxSum + 1];
            for (long[] row : memo) Arrays.fill(row, -1);
            System.out.println(solve(0, 0, 0, maxSum));
        }
    }

    static long solve(int pos, int mask, int curSum, int maxSum) {
        if (pos == n) {
            return curSum == s ? 1 : 0;
        }
        if (curSum > s) return 0;
        if (memo[mask][curSum] != -1) return memo[mask][curSum];

        long count = 0;
        for (int d = 0; d <= 9; d++) {
            if ((mask & (1 << d)) == 0) {
                int newSum = curSum + (pos + 1) * d;
                if (newSum <= s) {
                    count += solve(pos + 1, mask | (1 << d), newSum, maxSum);
                }
            }
        }
        memo[mask][curSum] = count;
        return count;
    }
}

