from functools import lru_cache

def solve():
    import sys
    input_data = sys.stdin.read().split()
    idx = 0
    results = []
    while idx < len(input_data):
        n = int(input_data[idx]); s = int(input_data[idx+1])
        idx += 2

        # Count sequences of n distinct digits from 0-9
        # where sum i*k_i = s (i from 1 to n)

        @lru_cache(maxsize=None)
        def dp(pos, used_mask, remaining):
            # pos: current position (1-indexed), from 1 to n
            # used_mask: bitmask of used digits
            # remaining: remaining sum needed
            if pos == n + 1:
                return 1 if remaining == 0 else 0
            if remaining < 0:
                return 0
            total = 0
            for d in range(10):
                if not (used_mask & (1 << d)):
                    new_remaining = remaining - pos * d
                    if new_remaining >= 0:
                        total += dp(pos + 1, used_mask | (1 << d), new_remaining)
            return total

        result = dp(1, 0, s)
        dp.cache_clear()
        results.append(result)

    for r in results:
        print(r)

