import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, s = map(int, data)

    # Digits are from 0..9, all must be distinct.
    if n > 10:
        print(0)
        return

    # dp[mask][sum] = number of ways to assign digits to first popcount(mask) positions
    # using exactly the digits in mask, obtaining weighted sum = sum.
    max_mask = 1 << 10
    dp = [dict() for _ in range(max_mask)]
    dp[0][0] = 1

    for mask in range(max_mask):
        used = mask.bit_count()
        if used >= n:
            continue
        pos = used + 1  # next position index (1-based)
        for cur_sum, cnt in dp[mask].items():
            for d in range(10):
                if not (mask >> d) & 1:
                    new_sum = cur_sum + pos * d
                    if new_sum > s:
                        continue
                    new_mask = mask | (1 << d)
                    dp[new_mask][new_sum] = dp[new_mask].get(new_sum, 0) + cnt

    ans = 0
    for mask in range(max_mask):
        if mask.bit_count() == n:
            ans += dp[mask].get(s, 0)

    print(ans)

