int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, s;
    cin >> n >> s;

    // dp[mask][sum] - number of ways using digits in mask to get sum
    vector<vector<int>> dp(1 << 10, vector<int>(s + 1, 0));
    dp[0][0] = 1;

    for (int mask = 0; mask < (1 << 10); mask++) {
        int pos = __builtin_popcount(mask); // how many digits already placed (1-indexed position)
        if (pos >= n) continue; // too many digits
        for (int sum = 0; sum <= s; sum++) {
            if (dp[mask][sum] == 0) continue;
            for (int d = 0; d <= 9; d++) {
                if (mask & (1 << d)) continue; // digit already used
                int new_sum = sum + (pos + 1) * d;
                if (new_sum > s) continue;
                dp[mask | (1 << d)][new_sum] += dp[mask][sum];
            }
        }
    }

    int ans = 0;
    for (int mask = 0; mask < (1 << 10); mask++) {
        if (__builtin_popcount(mask) == n) {
            ans += dp[mask][s];
        }
    }

    cout << ans << "\n";
    return 0;
}

