// dp[pos][mask][sum]:
// pos = how many positions already assigned (0..n)
// mask = used digits
// sum = current weighted sum

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, s;
    cin >> n >> s;

    // Maximum possible weighted sum for n<=10:
    // choose distinct digits 0..9, sum of i*digit
    // safe bound already covered by 386.
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;

    for (int pos = 0; pos < n; ++pos) {
        int weight = pos + 1;
        for (int mask = 0; mask < (1 << 10); ++mask) {
            for (int sum = 0; sum <= s; ++sum) {
                if (dp[pos][mask][sum] == 0) continue;
                for (int digit = 0; digit <= 9; ++digit) {
                    if (mask & (1 << digit)) continue; // no repeats
                    int nsum = sum + weight * digit;
                    if (nsum > s) continue;
                    dp[pos + 1][mask | (1 << digit)][nsum] += dp[pos][mask][sum];
                }
            }
        }
    }

    long long ans = 0;
    for (int mask = 0; mask < (1 << 10); ++mask) {
        ans += dp[n][mask][s];
    }

    cout << ans << '\n';
    return 0;
}
